local Orchardist = {}
local PRODUCTS = {
    apple_crop = { name = "Jabolka", appleSaplingCost = 1, waterCost = 1, time = 4, cost = 18, yield = 35, description = "Jabolka za jabolčnik in pitje." },
    pear_crop = { name = "Hruške", pearSaplingCost = 1, waterCost = 1, time = 4, cost = 22, yield = 40, prestige = 1, description = "Hruške za hruškovec." },
    cherry_crop = { name = "Češnje", cherrySaplingCost = 1, waterCost = 1, time = 5, cost = 35, yield = 45, prestige = 2, happiness = 1, description = "Češnje za sladice." },
    plum_crop = { name = "Slive", plumSaplingCost = 1, waterCost = 1, time = 5, cost = 40, yield = 50, prestige = 2, happiness = 1, description = "Slive za žganje in marmelade." },
    silver_blossom_orchard = { name = "Srebrno cvetoče sadje", cherrySaplingCost = 1, silverCost = 1, waterCost = 1, time = 8, cost = 110, yield = 70, prestige = 8, happiness = 2, description = "Sadje iz srebrno cvetočih dreves za plemiče." },
    royal_grand_orchard = { name = "Kraljevski veliki sadovnjak", appleSaplingCost = 2, pearSaplingCost = 1, goldCost = 1, silverCost = 1, jewelCost = 1, waterCost = 2, time = 14, cost = 800, yield = 100, prestige = 32, happiness = 8, description = "Veliki kraljevski sadovnjak z zlatom in dragulji za kronanje." },
}
local BUILDINGS = {
    workshop = { name = "Sadjarstvo postaja", cost = { gold = 220, wood = 130, stone = 100 }, upkeep = 5, qualityBonus = 5 },
    orchard = { name = "Sadovnjak", cost = { gold = 800, wood = 220, stone = 250, water = 10 }, upkeep = 20, qualityBonus = 18 },
    cider_press_barn = { name = "Tisčna staja", cost = { gold = 2000, wood = 350, stone = 600, silver = 25, iron = 8 }, upkeep = 50, qualityBonus = 30 },
    royal_orchard_atelier = { name = "Kraljevski atelje sadja", cost = { gold = 8200, wood = 600, stone = 900, gold = 60, jewel = 20 }, upkeep = 165, qualityBonus = 55, prestigeBonus = 40 },
}
Orchardist.appleSaplingStock = 22; Orchardist.pearSaplingStock = 18; Orchardist.cherrySaplingStock = 14; Orchardist.plumSaplingStock = 14; Orchardist.waterStock = 18; Orchardist.silverStock = 8; Orchardist.goldStock = 6; Orchardist.jewelStock = 6
Orchardist.productStock = {}; Orchardist.buildings = {}; Orchardist.maker = nil; Orchardist.activeMaking = {}; Orchardist.totalProducts = 0; Orchardist.dayTimer = 0
function Orchardist.init() Orchardist.appleSaplingStock=22; Orchardist.pearSaplingStock=18; Orchardist.cherrySaplingStock=14; Orchardist.plumSaplingStock=14; Orchardist.waterStock=18; Orchardist.silverStock=8; Orchardist.goldStock=6; Orchardist.jewelStock=6; Orchardist.productStock={}; Orchardist.buildings={}; Orchardist.maker=nil; Orchardist.activeMaking={}; Orchardist.totalProducts=0; Orchardist.dayTimer=0; print("[Orchardist] Royal Orchardist System initialized (6 products, 4 buildings)") end
function Orchardist.hireMaker(n,s) s=s or math.random(45,85); local c=460+s*10; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; Orchardist.maker={name=n or ("Sadjar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Sadjar najet: %s (spretnost: %d)",Orchardist.maker.name,s),"success") end; return true end
function Orchardist.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function Orchardist.build(id) local ok,e=Orchardist.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(Orchardist.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function Orchardist.getQualityBonus() local b=0; for _,bd in ipairs(Orchardist.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function Orchardist.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.appleSaplingCost and Orchardist.appleSaplingStock<(d.appleSaplingCost or 0) then return false,"Premalo jablan" end; if d.pearSaplingCost and Orchardist.pearSaplingStock<(d.pearSaplingCost or 0) then return false,"Premalo hrušk" end; if d.cherrySaplingCost and Orchardist.cherrySaplingStock<(d.cherrySaplingCost or 0) then return false,"Premalo češenj" end; if d.plumSaplingCost and Orchardist.plumSaplingStock<(d.plumSaplingCost or 0) then return false,"Premalo sliv" end; if d.waterCost and Orchardist.waterStock<(d.waterCost or 0) then return false,"Premalo vode" end; if d.silverCost and Orchardist.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and Orchardist.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and Orchardist.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if #Orchardist.buildings==0 then return false,"Potrebna delavnica" end; if not Orchardist.maker then return false,"Potreben sadjar" end; return true end
function Orchardist.make(pt,qty) qty=qty or 10; local ok,e=Orchardist.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.appleSaplingCost then Orchardist.appleSaplingStock=Orchardist.appleSaplingStock-d.appleSaplingCost*qty end; if d.pearSaplingCost then Orchardist.pearSaplingStock=Orchardist.pearSaplingStock-d.pearSaplingCost*qty end; if d.cherrySaplingCost then Orchardist.cherrySaplingStock=Orchardist.cherrySaplingStock-d.cherrySaplingCost*qty end; if d.plumSaplingCost then Orchardist.plumSaplingStock=Orchardist.plumSaplingStock-d.plumSaplingCost*qty end; if d.waterCost then Orchardist.waterStock=Orchardist.waterStock-d.waterCost*qty end; if d.silverCost then Orchardist.silverStock=Orchardist.silverStock-d.silverCost*qty end; if d.goldCost then Orchardist.goldStock=Orchardist.goldStock-d.goldCost*qty end; if d.jewelCost then Orchardist.jewelStock=Orchardist.jewelStock-d.jewelCost*qty end; local t=d.time; if Orchardist.maker then t=math.max(1,t-math.floor(Orchardist.maker.skill/12)) end; table.insert(Orchardist.activeMaking,{id="orchard_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,yield=d.yield or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function Orchardist.completeMaking(m) local q=1.0+(Orchardist.getQualityBonus()/100); if Orchardist.maker then q=q+(Orchardist.maker.skill/180) end; q=math.min(2.0,q); Orchardist.productStock[m.productType]=(Orchardist.productStock[m.productType] or 0)+m.quantity; Orchardist.totalProducts=Orchardist.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if Orchardist.maker then Orchardist.maker.itemsMade=Orchardist.maker.itemsMade+m.quantity; if math.random()<0.20 then Orchardist.maker.skill=math.min(100,Orchardist.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Sadje pridelano: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"orchard.completed",{productName=m.productName,yield=m.yield}) end end
function Orchardist.update(dt) if not _G.state then return end; Orchardist.dayTimer=Orchardist.dayTimer+dt; if Orchardist.dayTimer>=30 then Orchardist.dayTimer=0; for i=#Orchardist.activeMaking,1,-1 do local m=Orchardist.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then Orchardist.completeMaking(m); table.remove(Orchardist.activeMaking,i) end end; local tu=0; for _,bd in ipairs(Orchardist.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if Orchardist.maker then tu=tu+12 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function Orchardist.getStats() return {appleSaplingStock=Orchardist.appleSaplingStock,pearSaplingStock=Orchardist.pearSaplingStock,cherrySaplingStock=Orchardist.cherrySaplingStock,plumSaplingStock=Orchardist.plumSaplingStock,waterStock=Orchardist.waterStock,silverStock=Orchardist.silverStock,goldStock=Orchardist.goldStock,jewelStock=Orchardist.jewelStock,productStock=Orchardist.productStock,numBuildings=#Orchardist.buildings,hasMaker=Orchardist.maker~=nil,makerName=Orchardist.maker and Orchardist.maker.name or "—",makerSkill=Orchardist.maker and Orchardist.maker.skill or 0,activeMaking=#Orchardist.activeMaking,totalProducts=Orchardist.totalProducts} end
return Orchardist
